import re
from pathlib import Path

p=Path('index.html')
s=p.read_text(encoding='utf-8')
original=s

# Real delete button; add it dynamically in the final guard too, so this works even if
# the legacy modal markup has changed.
if 'id="deleteReportLink"' not in s:
    for anchor in ['<button class="btn danger" id="deleteTestItemLink"','<input type="file" id="reportFileInput"']:
        if anchor in s:
            s=s.replace(anchor,'<button class="btn danger" id="deleteReportLink" type="button" style="display:none">첨부파일 삭제</button>\n'+anchor,1)
            break

# Strict per-row upload. Never use a shared report path.
a=s.find('async function uploadReportV16(rowId,file){')
b=s.find('async function makeSignedReportUrlV16',a)
if a>=0 and b>a:
    fn='''async function uploadReportV16(rowId,file){\n  const targetNo=Number(rowId);\n  if(!targetNo||!file)throw new Error('Report 파일과 시험 항목을 확인하세요.');\n  const old=await getReportInfoV16(targetNo).catch(()=>null);\n  const row=DATA.find(r=>Number(r.No)===targetNo);\n  if(!row)throw new Error('선택한 시험 항목을 찾을 수 없습니다.');\n  const ext=((file.name||'').match(/\\.([A-Za-z0-9]+)$/)||['','bin'])[1].toLowerCase();\n  const token=(crypto.randomUUID?crypto.randomUUID().replace(/-/g,''):String(Date.now())+Math.random().toString(36).slice(2));\n  const path=`reports/${targetNo}/${Date.now()}_${token}.${ext}`;\n  const {error:upErr}=await supabaseClient.storage.from(REPORT_BUCKET_V16).upload(path,file,{upsert:false,contentType:file.type||'application/octet-stream'});\n  if(upErr)throw upErr;\n  const todayISO=new Date().toISOString().slice(0,10);\n  const status=row['Reliability Test Status']||'Not tested';\n  let start=row['Reliability Test Start Date']||null;\n  let end=row['Reliability Test Expected End Date']||null;\n  if(status==='신뢰성 진행 중'&&!start)start=todayISO;\n  if(status==='Finished'&&!start)start=todayISO;\n  if(status==='Finished'&&!end)end=todayISO;\n  const patch={report_path:path,report_filename:file.name,report_mime:file.type||null,reliability_start_date:start,reliability_expected_end_date:end,updated_at:new Date().toISOString()};\n  const {data,error:dbErr}=await supabaseClient.from('reliability_tests').update(patch).eq('id',targetNo).select('*').single();\n  if(dbErr){await supabaseClient.storage.from(REPORT_BUCKET_V16).remove([path]).catch(()=>{});throw dbErr;}\n  if(old?.report_path&&old.report_path!==path)await supabaseClient.storage.from(REPORT_BUCKET_V16).remove([old.report_path]).catch(()=>{});\n  return mapDbRow(data);\n}\n'''
    s=s[:a]+fn+s[b:]

# Remove duplicate statements left by older patch rounds.
s=re.sub(r"\s*document\.getElementById\('reportModal'\)\.dataset\.itemId\s*=\s*String\(no\)\s*;",'',s)
needle="  currentReportNo=String(no);currentReportFile=null;"
if needle in s and "currentReportNo=String(no);currentReportFile=null;document.getElementById('reportModal').dataset.itemId=String(no);" not in s:
    s=s.replace(needle,needle+"document.getElementById('reportModal').dataset.itemId=String(no);",1)
s=re.sub(r"const\s+deleteFileBtn\s*=\s*document\.getElementById\('deleteReportLink'\)\s*;",'',s)
s=re.sub(r"if\s*\(\s*deleteFileBtn\s*\)\s*deleteFileBtn\.style\.display\s*=\s*['\"]none['\"]\s*;",'',s)
open_anchor="  const openBtn=document.getElementById('openReportFile');openBtn.style.display='none';"
if open_anchor in s and "const deleteFileBtn=document.getElementById('deleteReportLink');if(deleteFileBtn)deleteFileBtn.style.display='none';" not in s:
    s=s.replace(open_anchor,open_anchor+"const deleteFileBtn=document.getElementById('deleteReportLink');if(deleteFileBtn)deleteFileBtn.style.display='none';",1)
s=s.replace("document.getElementById('deleteReportLink').onclick=()=>window.deleteReportNow();\n",'')
marker='window.deleteReportNow = async function(){'
if marker in s:
    s=s.replace(marker,"const __deleteReportLink=document.getElementById('deleteReportLink');if(__deleteReportLink)__deleteReportLink.onclick=()=>window.deleteReportNow();\n"+marker,1)

# Fill dates for any saved running/finished row when the fields are blank.
old_marker="  const statusValue=document.getElementById('mStatus').value||null;\n  let reliabilityStartDate=document.getElementById('mReliabilityStartDate').value||old['Reliability Test Start Date']||null;\n  let reliabilityExpectedEndDate=document.getElementById('mReliabilityExpectedEndDate').value||old['Reliability Test Expected End Date']||null;\n  const todayISO=new Date().toISOString().slice(0,10);\n  if(statusValue==='신뢰성 진행 중' && !reliabilityStartDate) reliabilityStartDate=todayISO;\n  if(statusValue==='Finished' && !reliabilityExpectedEndDate) reliabilityExpectedEndDate=todayISO;"
new_marker="  const statusValue=document.getElementById('mStatus').value||null;\n  let reliabilityStartDate=document.getElementById('mReliabilityStartDate').value||old['Reliability Test Start Date']||null;\n  let reliabilityExpectedEndDate=document.getElementById('mReliabilityExpectedEndDate').value||old['Reliability Test Expected End Date']||null;\n  const todayISO=new Date().toISOString().slice(0,10);\n  if(statusValue==='신뢰성 진행 중' && !reliabilityStartDate) reliabilityStartDate=todayISO;\n  if(statusValue==='Finished' && !reliabilityStartDate) reliabilityStartDate=todayISO;\n  if(statusValue==='Finished' && !reliabilityExpectedEndDate) reliabilityExpectedEndDate=todayISO;"
if old_marker in s:s=s.replace(old_marker,new_marker,1)

# Final guard: preserve registration drafts across navigation, make attachment deletion explicit,
# and render dates in the reliability/report table from the database.
guard=r'''\n<script id="reliabilityFinalGuard">\n(function(){\n  const DRAFT_KEY='sjit_reliability_report_draft_v2';\n  const $=id=>document.getElementById(id);\n  function modal(){return $('reportModal');}\n  function isOpen(){const m=modal();return !!(m&&m.classList.contains('show'));}\n  function fields(){return ['mRequestDate','mModel','mMaterial','mTestItem','mTestResult','mCpkReview','mResultBefore','mResultAfter','mStatus','mReliabilityStartDate','mReliabilityExpectedEndDate','mReportNo','mReportPublished','mPic','mCrNo','mTestQty','mLotNo','mProductionDate','mReason','mRemark'];}\n  function saveDraft(){if(!isOpen())return;const o={};fields().forEach(id=>{const e=$(id);if(e)o[id]=e.value;});try{sessionStorage.setItem(DRAFT_KEY,JSON.stringify(o));}catch(e){}}\n  function restoreDraft(){let o=null;try{o=JSON.parse(sessionStorage.getItem(DRAFT_KEY)||'null');}catch(e){}if(!o)return;fields().forEach(id=>{const e=$(id);if(e&&o[id]!==undefined&&e.value==='')e.value=o[id];});}\n  function clearDraft(){try{sessionStorage.removeItem(DRAFT_KEY);}catch(e){}}\n  function wireDraft(){fields().forEach(id=>{const e=$(id);if(e&&!e.dataset.draftWired){e.addEventListener('input',saveDraft);e.addEventListener('change',saveDraft);e.dataset.draftWired='1';}});}\n  function ensureDeleteButton(){\n    const m=modal();if(!m)return null;\n    let b=$('deleteReportLink');\n    if(!b){\n      b=document.createElement('button');b.id='deleteReportLink';b.type='button';b.className='btn danger';b.textContent='첨부파일 삭제';b.style.display='none';\n      const open=$('openReportFile');\n      if(open&&open.parentNode)open.parentNode.insertBefore(b,open.nextSibling);\n      else m.querySelector('.uploadbox')?.appendChild(b);\n    }\n    return b;\n  }\n  async function syncDeleteButton(){\n    const b=ensureDeleteButton();if(!b)return;\n    const no=Number(modal()?.dataset.itemId||window.currentReportNo||0);\n    if(!no){b.style.display='none';return;}\n    try{const r=await supabaseClient.from('reliability_tests').select('report_path').eq('id',no).maybeSingle();b.style.display=r?.data?.report_path?'inline-block':'none';}\n    catch(e){b.style.display='none';}\n  }\n  const oldShow=window.showReportModalV16;\n  if(typeof oldShow==='function'&&!oldShow.__draftWrapped){\n    window.showReportModalV16=function(){const r=oldShow.apply(this,arguments);setTimeout(()=>{wireDraft();restoreDraft();ensureDeleteButton();syncDeleteButton();},0);return r;};\n    window.showReportModalV16.__draftWrapped=true;\n  }\n  document.addEventListener('input',e=>{if(isOpen()&&e.target.matches('input,select,textarea'))saveDraft();},true);\n  document.addEventListener('change',e=>{if(isOpen()&&e.target.matches('input,select,textarea'))saveDraft();},true);\n  document.addEventListener('click',function(ev){\n    const nav=ev.target.closest('.nav button');if(nav&&isOpen())saveDraft();\n    const save=ev.target.closest('#saveManualBtn,#saveReportBtn,[data-action="save-report"]');if(save)setTimeout(()=>{if(!isOpen())clearDraft();},500);\n  },true);\n  // Clicking the dark backdrop must not silently discard a registration in progress.\n  document.addEventListener('click',function(ev){const m=modal();if(m&&ev.target===m&&isOpen()){ev.stopImmediatePropagation();}},true);\n\n  async function loadDates(){\n    try{\n      const {data}=await supabaseClient.from('reliability_tests').select('id,reliability_start_date,reliability_expected_end_date');\n      const map=new Map((data||[]).map(r=>[Number(r.id),r]));\n      document.querySelectorAll('table.report-table,table.manual-table').forEach(t=>{\n        const head=t.querySelector('thead tr');if(!head)return;\n        const ths=[...head.children];\n        let si=ths.findIndex(x=>(x.textContent||'').includes('TEST 시작일'));\n        let ei=ths.findIndex(x=>(x.textContent||'').includes('TEST 종료예정일'));\n        if(si<0){const th=document.createElement('th');th.textContent='TEST 시작일';head.appendChild(th);si=head.children.length-1;}\n        if(ei<0){const th=document.createElement('th');th.textContent='TEST 종료예정일';head.appendChild(th);ei=head.children.length-1;}\n        [...t.querySelectorAll('tbody tr')].forEach(tr=>{\n          const first=tr.children[0];if(!first)return;\n          const no=Number((first.textContent||'').replace(/[^0-9]/g,''));const r=map.get(no);if(!r)return;\n          while(tr.children.length<head.children.length){const td=document.createElement('td');tr.appendChild(td);}\n          tr.children[si].textContent=r.reliability_start_date||'-';\n          tr.children[ei].textContent=r.reliability_expected_end_date||'-';\n        });\n      });\n    }catch(e){}\n  }\n  setInterval(()=>{if(isOpen())syncDeleteButton();loadDates();},1500);\n  loadDates();\n})();\n</script>\n'''
# Remove any older guard versions before installing exactly one final guard.
s=re.sub(r'<script id="reliabilityFinalGuard">.*?</script>\s*', '', s, flags=re.S)
s=s.replace('</body>',guard+'</body>')

p.write_text(s,encoding='utf-8')
print('changed:',s!=original)
